create temporary table enterprise_ids(name text primary key,id uuid default gen_random_uuid());
insert into enterprise_ids(name) values('employee'),('manager'),('outsider');
create temporary table enterprise_results(name text,passed boolean);
grant select on enterprise_ids to authenticated;grant select,insert on enterprise_results to authenticated;
insert into auth.users(id,aud,role,email,raw_user_meta_data) select id,'authenticated','authenticated',name||'-enterprise@example.invalid','{}' from enterprise_ids;
insert into public.profiles(id,name,role) select id,name,case when name='manager' then 'manager' else 'employee' end from enterprise_ids;
insert into private.settings(key,value) values('review_hash',encode(extensions.digest('test-server','sha256'),'hex')) on conflict(key) do update set value=excluded.value;
set role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='employee'),false);
do $$declare d public.documents;r jsonb;input jsonb;blocked boolean;path text;
begin
 input:='{"supplier":"Source Vendor","invoice_number":"SOURCE-001","invoice_date":"2026-10-01","due_date":"2026-11-01","currency":"INR","category":"Other","items":[{"description":"Paper","quantity":10,"unit_price":50}],"tax":0,"total":700,"notes":"","uncertainties":[]}';
 path:=auth.uid()::text||'/source.txt';insert into storage.objects(bucket_id,name) values('invoice-documents',path);d:=public.register_document(path,'source.txt','text/plain',100);
 blocked:=false;begin perform public.start_document_read(d.id,'wrong',false);exception when others then blocked:=true;end;insert into enterprise_results values('Browser cannot forge server extraction',blocked);
 d:=public.start_document_read(d.id,'test-server',false);d:=public.finish_document_read(d.id,d.run_id,'test-server',input,'Original printed total: 500',repeat('a',64),'local-text','');
 insert into enterprise_results values('Initial extraction and source snapshot saved',d.extracted=input and d.source_text='Original printed total: 500');
 r:=public.commit_document(d.id,'test-server');insert into enterprise_results values('Server automatically creates complete invoice',r->>'invoice_id' is not null);
 insert into enterprise_results values('Wrong extracted total preserved and flagged',(select total=700 and status='needs_correction' from public.invoices where id=(r->>'invoice_id')::uuid));
 blocked:=false;begin perform public.amend_invoice((r->>'invoice_id')::uuid,jsonb_set(input,'{total}','500'));exception when others then blocked:=true;end;insert into enterprise_results values('Employee cannot edit uploaded invoice through old RPC',blocked);
 blocked:=false;begin perform public.create_invoice(input,gen_random_uuid());exception when others then blocked:=true;end;insert into enterprise_results values('Employee cannot substitute arbitrary invoice facts',blocked);
 blocked:=false;begin perform public.review_document(d.id,0,jsonb_set(input,'{total}','500'),'Employee tries editing','approve');exception when others then blocked:=true;end;insert into enterprise_results values('Manager correction RPC rejects employee',blocked);
 blocked:=false;begin update public.documents set extracted='{}' where id=d.id;exception when others then blocked:=true;end;insert into enterprise_results values('Original snapshot cannot be overwritten by client',blocked);
 d:=public.start_document_read(d.id,'test-server',false);insert into enterprise_results values('Repeated read preserves initial snapshot',(d.extracted->>'total')::numeric=700);
end $$;
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='outsider'),false);
insert into enterprise_results values('Unrelated employee cannot see documents',(select count(*)=0 from public.documents));
insert into enterprise_results values('Search does not leak another employee invoice',(public.search_invoices('','',0,100000000,0)->>'total')::int=0);
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='manager'),false);
do $$declare d public.documents;r jsonb;input jsonb;blocked boolean;
begin
 select * into d from public.documents where filename='source.txt';input:=jsonb_set(d.extracted,'{total}','500');
 blocked:=false;begin perform public.review_document(d.id,99,input,'Stale manager edit','approve');exception when others then blocked:=true;end;insert into enterprise_results values('Stale revision rejected',blocked);
 r:=public.review_document(d.id,0,jsonb_set(input,'{total}','600'),'Test incorrect extraction correction','approve');
 insert into enterprise_results values('Incorrect manager correction is saved but cannot approve',(r->>'blocked')::boolean and r->>'state'='needs_correction');
 insert into enterprise_results values('Failed approval preserves immutable original',(select (extracted->>'total')::numeric=700 and (review_data->>'total')::numeric=600 from public.documents where id=d.id));
 r:=public.review_document(d.id,1,input,'Corrected extraction to original total 500','approve');insert into enterprise_results values('One manager corrects and approves directly',r->>'state'='approved');
 insert into enterprise_results values('Original and current values remain separate',(select (extracted->>'total')::numeric=700 and (review_data->>'total')::numeric=500 from public.documents where id=d.id));
 insert into enterprise_results values('Correction and approval audited separately',(select count(*)=3 from public.document_audit where document_id=d.id));
 insert into enterprise_results values('Audit has before and after values',exists(select 1 from public.document_audit where document_id=d.id and action='manager_correction' and (before_data->>'total')::numeric=600 and (after_data->>'total')::numeric=500));
 blocked:=false;begin perform public.review_document(d.id,3,input,'Edit after approval','save');exception when others then blocked:=true;end;insert into enterprise_results values('Approved document locked',blocked);
 blocked:=false;begin update public.document_audit set reason='tampered';exception when others then blocked:=true;end;insert into enterprise_results values('Client cannot rewrite correction audit',blocked);
end $$;
do $$declare d public.documents;r jsonb;input jsonb;path text;
begin
 input:='{"supplier":"Manager Vendor","invoice_number":"OWN-001","invoice_date":"2026-10-02","due_date":"2026-11-01","currency":"INR","category":"Other","items":[{"description":"Pen","quantity":1,"unit_price":50}],"tax":0,"total":50,"notes":"","uncertainties":[]}';
 path:=auth.uid()::text||'/manager.txt';insert into storage.objects(bucket_id,name) values('invoice-documents',path);d:=public.register_document(path,'manager.txt','text/plain',100);d:=public.start_document_read(d.id,'test-server',false);d:=public.finish_document_read(d.id,d.run_id,'test-server',input,'Manager original total 50',repeat('b',64),'local-text','');r:=public.commit_document(d.id,'test-server');r:=public.review_document(d.id,0,input,'Verified original and extracted figures','approve');insert into enterprise_results values('Manager can approve own upload without second manager',r->>'state'='approved');
end $$;
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='employee'),false);
do $$declare d public.documents;r jsonb;input jsonb;path text;blocked boolean;
begin
 select jsonb_set(review_data,'{invoice_number}','"NEW-NUMBER"') into input from public.documents where filename='source.txt';
 path:=auth.uid()::text||'/duplicate.txt';insert into storage.objects(bucket_id,name) values('invoice-documents',path);d:=public.register_document(path,'duplicate.txt','text/plain',100);d:=public.start_document_read(d.id,'test-server',false);d:=public.finish_document_read(d.id,d.run_id,'test-server',input,'Same file',repeat('a',64),'local-text','');r:=public.commit_document(d.id,'test-server');insert into enterprise_results values('Re-uploaded identical original blocked',(r->>'needs_input')::boolean and r->>'invoice_id' is null);
 input:=jsonb_set(input,'{invoice_number}','"MISSING-001"');input:=jsonb_set(input,'{due_date}','null');input:=jsonb_set(input,'{uncertainties}','["Due date unreadable"]');path:=auth.uid()::text||'/missing.txt';insert into storage.objects(bucket_id,name) values('invoice-documents',path);d:=public.register_document(path,'missing.txt','text/plain',100);d:=public.start_document_read(d.id,'test-server',false);d:=public.finish_document_read(d.id,d.run_id,'test-server',input,'Missing date',repeat('c',64),'local-text','');r:=public.commit_document(d.id,'test-server');insert into enterprise_results values('Missing details routed to manager without inventing values',(r->>'needs_input')::boolean and r->>'invoice_id' is null);
 for n in 1..20 loop perform public.reserve_assistant();end loop;blocked:=false;begin perform public.reserve_assistant();exception when others then blocked:=true;end;insert into enterprise_results values('AI assistant request budget enforced',blocked);
end $$;
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='manager'),false);
do $$declare d public.documents;r jsonb;blocked boolean;
begin
 select * into d from public.documents where filename='duplicate.txt';blocked:=false;begin perform public.review_document(d.id,0,d.extracted,'Attempt override duplicate original','approve');exception when others then blocked:=true;end;insert into enterprise_results values('Manager cannot bypass original duplicate gate',blocked);
 r:=public.review_document(d.id,0,null,'Rejected duplicate original upload','reject');insert into enterprise_results values('Duplicate document can be rejected',r->>'state'='rejected');
 select * into d from public.documents where filename='missing.txt';r:=public.review_document(d.id,0,null,'Request readable original from supplier','reject');insert into enterprise_results values('Incomplete document can be rejected without invented facts',r->>'state'='rejected');
end $$;
reset role;
insert into public.invoices(client_id,created_by,supplier,invoice_number,invoice_date,due_date,category,items,tax,total,status) select gen_random_uuid(),(select id from enterprise_ids where name='employee'),'Scale Supplier','SCALE-'||n,'2026-10-01','2026-11-01','Other','[{"description":"Test","quantity":1,"unit_price":10}]',0,10,'submitted' from generate_series(1,2000) n;
set role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='employee'),false);
insert into enterprise_results values('Search counts 2,000 invoices',(public.search_invoices('Scale Supplier','',0,100000000,0)->>'total')::int=2000);
insert into enterprise_results values('Search returns 20 rows per page',jsonb_array_length(public.search_invoices('Scale Supplier','',0,100000000,0)->'invoices')=20);
insert into enterprise_results values('Search reaches beyond first 1,000',jsonb_array_length(public.search_invoices('Scale Supplier','',0,100000000,1500)->'invoices')=20);
insert into enterprise_results values('Specific invoice search works',(public.search_invoices('SCALE-1999','',0,100000000,0)->>'total')::int=1);
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='outsider'),false);
insert into enterprise_results values('Search and audit remain private',(public.search_invoices('Scale Supplier','',0,100000000,0)->>'total')::int=0 and (select count(*)=0 from public.document_audit));
reset role;
